--
-- Table structure for table `wp_mwai_mcp_oauth_clients`
--

DROP TABLE IF EXISTS `wp_mwai_mcp_oauth_clients`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wp_mwai_mcp_oauth_clients` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `client_id` varchar(64) COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `client_secret_hash` varchar(64) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `client_name` varchar(255) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `redirect_uris` longtext COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `grant_types` varchar(255) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'authorization_code,refresh_token',
  `token_endpoint_auth_method` varchar(32) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'none',
  `scope` varchar(255) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `created` datetime NOT NULL,
